-- Mission Plaza custody doors for ox_doorlock (table `ox_doorlock` from ox_doorlock/sql/ox_doorlock.sql).
-- World pivots of the MLO door entities.
-- groups: {"police":0} is a placeholder - set your police job name(s) and minimum grades (we suggest a
-- sergeant/custody grade for A1, A2, G1, S1). state 1 = locked. Interlocks (A1<->A2, E1<->S1) need interlock_ox.lua.
-- Re-running this file replaces only these doors (names starting nobs_ukpd_d11_).
DELETE FROM `ox_doorlock` WHERE `name` LIKE 'nobs\_ukpd\_d11\_%';
-- nobs_ukpd_d11_g1 = Custody garage entry (G1), nobs_ukpd_d11_s1 = Custody staff entry (S1), nobs_ukpd_d11_e1 = Cell hall response door (E1), nobs_ukpd_d11_s2 = Custody staff side (S2), nobs_ukpd_d11_s3 = Custody walk-in (S3), nobs_ukpd_d11_s4 = Custody desk staff gate (S4), nobs_ukpd_d11_a1 = Airlock outer (A1), nobs_ukpd_d11_a2 = Airlock cage gate (A2), nobs_ukpd_d11_r1 = ID suite (R1), nobs_ukpd_d11_r2 = Medical / FME (R2), nobs_ukpd_d11_r3 = Interview 1 (R3), nobs_ukpd_d11_r4 = Interview 2 / consult (R4), nobs_ukpd_d11_h1 = Holding 1 (H1), nobs_ukpd_d11_h2 = Holding 2 (H2), nobs_ukpd_d11_x1 = Strip search (X1), nobs_ukpd_d11_w1 = Detainee shower / WC (W1), nobs_ukpd_d11_c1 = Cell 1 (C1), nobs_ukpd_d11_c2 = Cell 2 (C2), nobs_ukpd_d11_c3 = Cell 3 (C3), nobs_ukpd_d11_c4 = Cell 4 (C4), nobs_ukpd_d11_c5 = Cell 5 (C5), nobs_ukpd_d11_c6 = Cell 6 (C6), nobs_ukpd_d11_c7 = Cell 7 (C7), nobs_ukpd_d11_c8 = Cell 8 (C8)
